const issues: any[] = [];
for (let page = 1; page <= 50; page++) {
  const res: any = await tools.list_issues({ repo: "acme/web", state: "open", label: "perf", page });
  const arr: any[] = Array.isArray(res) ? res : (res?.items ?? res?.issues ?? []);
  if (!arr || arr.length === 0) break;
  issues.push(...arr);
  if (arr.length < 50) break;
}

const seen = new Set<number>();
const targets: { number: number; login: string }[] = [];
for (const i of issues) {
  const num = i.number ?? i.num;
  if (num == null || seen.has(num)) continue;
  seen.add(num);
  const full: any = await tools.get_issue({ repo: "acme/web", number: num });
  const state = full?.state ?? i.state;
  const labels: string[] = (full?.labels ?? i.labels ?? []).map((l: any) => (typeof l === "string" ? l : l.name));
  const login: string | null =
    full?.assignee?.login ?? (typeof full?.assignee === "string" ? full.assignee : null);
  if (state === "open" && labels.includes("perf") && login) {
    targets.push({ number: num, login });
  }
}

const results: any[] = [];
for (const t of targets) {
  try {
    await tools.post_comment({ repo: "acme/web", number: t.number, body: `ping @${t.login}` });
    results.push({ number: t.number, login: t.login, ok: true });
  } catch (e: any) {
    results.push({ number: t.number, login: t.login, ok: false, error: String(e?.message ?? e) });
  }
}

return { candidates: issues.length, uniqueChecked: seen.size, commented: results.length, results };
